function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's must have between 1 and 10^5 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  return null;
}

