function numSplits(s) {
  const rightCount = new Map();
  for (const ch of s) {
    rightCount.set(ch, (rightCount.get(ch) ?? 0) + 1);
  }

  const leftSeen = new Set();
  let good = 0;

  for (let i = 0; i < s.length - 1; i++) {
    const ch = s[i];
    leftSeen.add(ch);
    rightCount.set(ch, rightCount.get(ch) - 1);
    if (rightCount.get(ch) === 0) {
      rightCount.delete(ch);
    }
    if (leftSeen.size === rightCount.size) {
      good++;
    }
  }

  return good;
}

