function numSplits(s) {
  // Rebuild both halves for every cut and count their distinct letters directly.
  let count = 0;
  for (let k = 1; k < s.length; k++) {
    if (new Set(s.slice(0, k)).size === new Set(s.slice(k)).size) count++;
  }
  return count;
}

