function generate(rand, size) {
  const length = size === 'large' ? 8000 + Math.floor(rand() * 2001) : 1 + Math.floor(rand() * 12);
  const alphabet = size === 'large' ? 1 + Math.floor(rand() * 26) : 1 + Math.floor(rand() * 4);
  let s = '';
  for (let i = 0; i < length; i++) s += String.fromCharCode(97 + Math.floor(rand() * alphabet));
  return [s];
}
